import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  RoomMessageEventMessageType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { getEventId } from "modules/matrix-client/utils";
import { useCallback, useEffect, useRef, useState } from "react";

//TODO: Make a timeline module

const PAGE_SIZE = 50;

interface UseMediaTimelineProps {
  room: RoomInterface | undefined;
  roomId: string;
}

export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [reachedStart, setReachedStart] = useState(false);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);
  const reachedStartRef = useRef(false);
  const isPaginatingRef = useRef(false);

  const loadMore = useCallback(async () => {
    if (
      !timelineRef.current ||
      isPaginatingRef.current ||
      reachedStartRef.current
    ) {
      return;
    }
    isPaginatingRef.current = true;
    try {
      const hitStart = await timelineRef.current.paginateBackwards(PAGE_SIZE);
      if (hitStart) {
        reachedStartRef.current = true;
        setReachedStart(true);
      }
    } catch (error) {
      console.error("Failed to paginate media timeline:", error);
    } finally {
      isPaginatingRef.current = false;
    }
  }, []);

  const upsertMediaItems = useCallback((incoming: EventTimelineItem[]) => {
    setMediaItems((prev) => {
      const next = [...prev];
      for (const event of incoming) {
        const id = getEventId(event);
        if (!id || eventIdsRef.current.has(id)) continue;

        eventIdsRef.current.add(id);
        next.push(event);
      }
      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
    });
  }, []);

  useEffect(() => {
    if (!room) return;

    setLoading(true);
    setMediaItems([]);
    setReachedStart(false);
    reachedStartRef.current = false;
    isPaginatingRef.current = false;
    eventIdsRef.current.clear();

    let timelineListenerHandle: TaskHandleInterface | null = null;

    const initMediaTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.OnlyMessage({
            types: [
              RoomMessageEventMessageType.Image,
              RoomMessageEventMessageType.Video,
              RoomMessageEventMessageType.File,
              RoomMessageEventMessageType.Audio,
            ],
          }),
          internalIdPrefix: "media_",
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.Disabled,
          reportUtds: false,
        });

        timelineRef.current = timeline;

        // Set up timeline listener for updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            diffs.forEach((diff) => {
              const change = diff.tag;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  const newItems = diff.inner.values;
                  if (newItems.length) {
                    const eventItems = newItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);
                    if (eventItems.length > 0) upsertMediaItems(eventItems);
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert:
                case TimelineDiff_Tags.PushFront:
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) upsertMediaItems([ev]);
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setMediaItems((prev) => {
                      const existingIndex = prev.findIndex(
                        (item) => getEventId(item) === id,
                      );
                      if (existingIndex >= 0) {
                        const next = [...prev];
                        next[existingIndex] = ev;
                        return next;
                      }
                      return prev;
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  setMediaItems((prev) => {
                    const next = prev.filter((_, idx) => idx !== removeIndex);
                    eventIdsRef.current = new Set(
                      next
                        .map((item) => getEventId(item))
                        .filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  if (resetItems.length) {
                    const eventItems = resetItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    const seenIds = new Set<string>();
                    const newMediaItems: EventTimelineItem[] = [];

                    for (const event of eventItems) {
                      const id = getEventId(event);
                      if (id && !seenIds.has(id)) {
                        seenIds.add(id);
                        newMediaItems.push(event);
                      }
                    }

                    eventIdsRef.current = seenIds;
                    setMediaItems(
                      newMediaItems.sort(
                        (a, b) => Number(b.timestamp) - Number(a.timestamp),
                      ),
                    );
                  }
                  break;
                }
                case TimelineDiff_Tags.Clear: {
                  eventIdsRef.current.clear();
                  setMediaItems([]);
                  break;
                }
                default:
                  break;
              }
            });
          },
        });

        // Load one initial page so the viewer/gallery has something to show.
        // Consumers drive further pagination via loadMore() on scroll/swipe.
        isPaginatingRef.current = true;
        try {
          const hitStart = await timeline.paginateBackwards(PAGE_SIZE);
          if (hitStart) {
            reachedStartRef.current = true;
            setReachedStart(true);
          }
        } finally {
          isPaginatingRef.current = false;
        }

        setLoading(false);
      } catch (error) {
        console.error("Failed to initialize media timeline:", error);
        setLoading(false);
      }
    };

    initMediaTimeline();

    return () => {
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
    };
  }, [roomId, room, upsertMediaItems]);

  return {
    mediaItems,
    loading,
    reachedStart,
    loadMore,
  };
};

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  type RoomInterface,
  TimelineItemContent_Tags,
  type VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { getEventId } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useMemo, useState } from "react";
import { StyleSheet } from "react-native";
import { useMediaTimeline } from "screens/room-media/hooks";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { FilesList } from "../files-list";
import { MediaList } from "../media-list";

interface Props {
  room: RoomInterface;
}

type Tab = "media" | "files";

function isMediaItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.Image || tag === MessageType_Tags.Video;
    }
  }
  return false;
}

function isFileItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.File || tag === MessageType_Tags.Audio;
    }
  }
  return false;
}

export const MediaGallery: FC<Props> = ({ room }) => {
  const { mediaItems: allItems, loading, loadMore } = useMediaTimeline({
    room,
    roomId: room.id(),
  });
  const [activeTab, setActiveTab] = useState<Tab>("media");
  const mediaItems = useMemo(() => allItems.filter(isMediaItem), [allItems]);
  const fileItems = useMemo(() => allItems.filter(isFileItem), [allItems]);
  const isMediaEmpty = !mediaItems.length;
  const isFileEmpty = !fileItems.length;
  const setMediaViewerPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);

  const handleSetActiveImageUri = (
    _uri: string | null,
    type?: "image" | "video",
    _content?: ImageMessageContent | VideoMessageContent,
    event?: EventTimelineItem,
  ) => {
    if (!type || !event) return;
    const eventId = getEventId(event);
    if (!eventId) return;
    setMediaViewerPayload({
      roomId: room.id(),
      initialEventId: eventId,
      initialEvent: event,
    });
  };

  return (
    <Block flex={1}>
      <Block flexDirection="row" margins={{ marginBottom: 16 }}>
        {(["media", "files"] as Tab[]).map((tab) => (
          <Button.Wrapper
            key={tab}
            onPress={() => setActiveTab(tab)}
            style={styles.tab}
          >
            <Block
              align="center"
              paddings={[10, 0]}
              border={{
                borderBottomWidth: 2,
                borderBottomColor:
                  activeTab === tab ? Colors.primary : Colors.white20,
              }}
            >
              <Text
                size={TextSize.small}
                color={activeTab === tab ? Colors.white : Colors.white50}
                textTransform="capitalize"
              >
                {tab}
              </Text>
            </Block>
          </Button.Wrapper>
        ))}
      </Block>

      {activeTab === "media" ? (
        <Block flex={1}>
          <MediaList
            items={mediaItems}
            loading={loading}
            isEmpty={isMediaEmpty}
            onPressItem={handleSetActiveImageUri}
            onEndReached={loadMore}
          />
        </Block>
      ) : (
        <FilesList
          items={fileItems}
          loading={loading}
          isEmpty={isFileEmpty}
          onEndReached={loadMore}
        />
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  tab: {
    flex: 1,
  },
});

